import java.util.*;
import java.io.*;

public class Main {
    static final long K = 1000000007L;
    static List<List<Long>> groupVectors = new ArrayList<>();
    static long[] popcountCounts;
    static long[] probabilities;
    static long[] temp;
    static Map<Long, Long>[] dpMap;
    static int n;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        int maxStates = 1 << n;

        // Initialize groupVectors
        for (int i = 0; i <= 8; i++) {
            groupVectors.add(new ArrayList<>());
        }

        popcountCounts = new long[maxStates];
        probabilities = new long[n];
        temp = new long[n];

        // Precompute group vectors based on popcount
        for (int idx_i = 0; idx_i < maxStates; idx_i++) {
            int count = Integer.bitCount(idx_i);
            popcountCounts[idx_i] = groupVectors.get(count).size();
            groupVectors.get(count).add((long) idx_i);
        }

        // Initialize dpMap array
        dpMap = new HashMap[n + 1];
        for (int i = 0; i <= n; i++) {
            dpMap[i] = new HashMap<>();
        }

        // Read input
        int lineIndex = 0;
        String line;
        // Read probabilities for each of the n iterations
        for (int i = 0; i < n; i++) {
            line = br.readLine();
            String[] parts = line.trim().split("\\s+");
            for (int j = 0; j < n; j++) {
                long prob = Long.parseLong(parts[j]);
                probabilities[j] = (prob * 570000004L) % K;
            }

            // Initialize dp for the current iteration
            if (i == 0) {
                // Base case
                dpMap[0].put(1L, 1L);
            }

            Map<Long, Long> currentDP = dpMap[i];
            Map<Long, Long> nextDP = new HashMap<>();

            for (Map.Entry<Long, Long> stateEntry : currentDP.entrySet()) {
                long stateMask = stateEntry.getKey();
                long stateProb = stateEntry.getValue();

                // Reset temp array
                Arrays.fill(temp, 0);

                // Build temp array based on current state
                for (long m : groupVectors.get((int) popcountCounts[(int) stateMask])) {
                    int popCountM = (int) (long) popcountCounts[(int) m];
                    if (((stateMask >> popCountM) & 1) != 0) {
                        for (int j = 0; j < n; j++) {
                            if (((m >> j) & 1) == 0) {
                                int newPopCount = (int) (popcountCounts[(int) (m | (1L << j))]);
                                temp[j] |= (1L << newPopCount);
                            }
                        }
                    }
                }

                // Iterate over all subsets of n
                int totalSubsets = 1 << n;
                for (int msk = 0; msk < totalSubsets; msk++) {
                    long X = 1;
                    long M = 0;
                    for (int j = 0; j < n; j++) {
                        if (((msk >> j) & 1) != 0) {
                            M |= temp[j];
                            X = (X * probabilities[j]) % K;
                        } else {
                            X = (X * (K - probabilities[j]) + K) % K;
                        }
                    }
                    long prevVal = nextDP.getOrDefault(M, 0L);
                    nextDP.put(M, (prevVal + stateProb * X) % K);
                }
            }
            dpMap[i + 1] = nextDP;
        }

        // Output the result
        System.out.println(dpMap[n].getOrDefault(1L, 0L));
    }
}
